import rdata, os
DATA_DIR = '/home/ubuntu/.agent-ml-research-idea_gen_0520_2/projects/irt_equated_bench_regen/artifacts/metabench_data/benchmark-data'

# Check mmlu-sub.rds with rdata
fpath = os.path.join(DATA_DIR, 'mmlu-sub.rds')
parsed = rdata.parser.parse_file(fpath)
converted = rdata.conversion.convert(parsed)
print('Type:', type(converted))
if isinstance(converted, dict):
    print('Keys:', list(converted.keys())[:20])
    for k, v in list(converted.items())[:5]:
        print(f'  {k}: type={type(v).__name__}', end='')
        if hasattr(v, 'shape'):
            print(f' shape={v.shape}', end='')
            if hasattr(v, 'columns'):
                print(f' cols={list(v.columns)[:10]}')
            else:
                print()
        elif hasattr(v, '__len__'):
            print(f' len={len(v)}')
        else:
            print(f' val={v}')
elif hasattr(converted, '__len__'):
    print('Length:', len(converted))
    for i, item in enumerate(converted[:3]):
        print(f'  [{i}]: type={type(item).__name__}')
